581:    fn admit_new_task_with_inputs(
582:        &self,
583:        request: &TaskRunRequest,
584:        request_identity_digest: String,
585:        inputs: &[InputBindingRequest],
586:    ) -> RuntimeResult<String> {
587:        match request.execution.execution_target {
588:            super::ExecutionTarget::LocalLinux => {
589:                if request.execution.execution_profile != super::ExecutionProfile::ContainedLocal {
590:                    return Err(RuntimeError::invalid(
591:                        "local_linux immutable input bindings require contained_local execution",
592:                        "execution.executionProfile",
593:                    ));
594:                }
595:            }
596:            super::ExecutionTarget::WindowsNative => {
597:                if request.execution.execution_profile != super::ExecutionProfile::TrustedLocal {
598:                    return Err(RuntimeError::invalid(
599:                        "windows_native immutable input bindings require trusted_local execution",
600:                        "execution.executionProfile",
601:                    ));
602:                }
603:                if request.execution.windows_authority != super::WindowsAuthority::Limited {
604:                    return Err(RuntimeError::invalid(
605:                        "windows_native immutable input bindings support limited authority only",
606:                        "execution.windowsAuthority",
607:                    ));
608:                }
609:                validate_windows_input_relative_paths(
610:                    inputs
611:                        .iter()
612:                        .map(|input| input.presentation_relative_path.as_str()),
613:                )?;
614:            }
615:        }
616:        validate_new_admission_policy(
617:            request,
618:            self.executor.max_runtime_ms,
619:            self.executor.max_output_bytes,
620:        )?;
621:        self.reconcile_recoverable_orphans()?;
622:        let _ = self.reconcile_workspace(&request.execution.workspace_id)?;
623:        let mut plan = self.resolve_plan(request)?;
624:        let admission_ids = self.registry.preallocate_admission_ids();
625:        let prepared = self.materialize_input_bindings(
626:            request,
627:            &request_identity_digest,
628:            &admission_ids.job_id,
629:            inputs,
630:        )?;
631:        plan.input_set_id = Some(prepared.input_set_id.clone());
632:        plan.effective_inputs = prepared.effective_inputs.clone();
633:        let input_root = match plan.execution_target {
634:            super::ExecutionTarget::LocalLinux => CONTAINED_INPUT_ROOT.to_string(),
635:            super::ExecutionTarget::WindowsNative => {
636:                windows_input_presentation_root(&plan, &prepared.input_set_id)?
637:            }
638:        };
639:        set_environment_value_case_insensitive(
640:            &mut plan.env,
641:            "ORDIVON_INPUT_ROOT",
642:            input_root.clone(),
643:        );
644:        for step in &mut plan.steps {
645:            set_environment_value_case_insensitive(
646:                &mut step.env,
647:                "ORDIVON_INPUT_ROOT",
648:                input_root.clone(),
649:            );
650:        }
651:        let submit = SubmitRequest {
652:            schema_version: RUNTIME_SCHEMA_VERSION,
653:            client_request_id: request.client_request_id.clone(),
654:            request_identity_digest: Some(request_identity_digest),
655:            execution_provider: Some(
656:                self.current_execution_provider_snapshot(request.execution.execution_target)?,
657:            ),
658:            runtime_release_effect: None,
659:            host_dependencies: Vec::new(),
660:            plan,
661:            global_limit: request.global_limit,
662:        };
663:        match self.registry.submit_preallocated(&submit, &admission_ids) {
664:            Ok(AdmissionOutcome::Created(created)) => {
665:                let job_id = created.job.job_id.clone();
666:                self.ensure_job_input_ownership(&job_id)
667:                    .map_err(|error| error.with_operation_id(job_id.clone()))?;
668:                self.ensure_attempt_dispatched(&created.attempt)
669:                    .map_err(|error| error.with_operation_id(job_id.clone()))?;
670:                Ok(job_id)
671:            }
672:            Ok(AdmissionOutcome::Existing { job }) => {
673:                self.discard_prepared_input_set(&prepared.prepared_root)?;
674:                Ok(job.job_id)
675:            }
676:            Err(error) => {
677:                self.discard_prepared_input_set(&prepared.prepared_root)?;
678:                Err(error)
679:            }
680:        }
681:    }
